int init_ip_example_proto_struct(void)
{
    protocol_t *protocol_struct;
    size_t i;

    /* mmt-dpi ignores a protocol name that is already registered (names
     * compare case-insensitively): refuse to load instead. */
    if (get_protocol_id_by_name(PROTO_IP_EXAMPLE_ALIAS) != 0) {
        mmt_log_error("init_ip_example_proto_struct: protocol name %s is already registered", PROTO_IP_EXAMPLE_ALIAS);
        return 0;
    }
    protocol_struct = init_protocol_struct_for_registration(PROTO_IP_EXAMPLE, PROTO_IP_EXAMPLE_ALIAS);
    if (protocol_struct == NULL) {
        mmt_log_error("init_ip_example_proto_struct: protocol id %d is out of range or already registered", PROTO_IP_EXAMPLE);
        return 0;
    }
    for (i = 0; i < sizeof(ip_example_attributes_metadata) / sizeof(ip_example_attributes_metadata[0]); i++) {
        if (!register_attribute_with_protocol(protocol_struct, &ip_example_attributes_metadata[i])) {
            mmt_log_error("init_ip_example_proto_struct: cannot register attribute %s", ip_example_attributes_metadata[i].alias);
            return 0;
        }
    }
    if (!register_classification_function(protocol_struct, ip_example_hook_classify_next)) {
        mmt_log_error("init_ip_example_proto_struct: cannot register the classify_next function");
        return 0;
    }
    register_proto_context_init_cleanup_function(protocol_struct, ip_example_hook_context_init, ip_example_hook_context_cleanup, NULL);
    register_sessionizer_function(protocol_struct, ip_example_hook_sessionizer, ip_example_hook_session_cleanup, ip_example_hook_session_compare);
    if (!register_protocol(protocol_struct, PROTO_IP_EXAMPLE)) {
        mmt_log_error("init_ip_example_proto_struct: cannot register protocol %d", PROTO_IP_EXAMPLE);
        return 0;
    }
    if (!register_classification_function_with_parent_protocol(99 /* PROTO_ETHERNET */, ip_example_classify_after_ethernet, 5)) {
        mmt_log_error("init_ip_example_proto_struct: cannot attach to the parent protocol ethernet");
        return 0;
    }
    /* User code (src/ip_example_impl.c) attaches the protocol to its other parents. */
    if (!ip_example_hook_register_parents(protocol_struct)) {
        mmt_log_error("init_ip_example_proto_struct: ip_example_hook_register_parents() failed");
        return 0;
    }
    return 1;
}

#ifndef CORE
int init_proto(void)
{
    return init_ip_example_proto_struct();
}
#endif
